import {products,stores,categories,productById,storeById,money,discount,imageUrl,href} from './data.js';
import {icon} from './icons.js';
import * as S from './store.js';

const app=document.querySelector('#app'), modal=document.querySelector('#modal'), drawer=document.querySelector('#mobile-nav');
const page=document.body.dataset.page || 'home', query=new URLSearchParams(location.search);
const ui={category:categories.includes(query.get('category'))?query.get('category'):'Todo',search:query.get('q')||'',sort:query.get('sort')||'featured',limit:8,tab:'orders',quantity:1};
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=value=>{const d=new Date(value);return Number.isNaN(d.getTime())?'Fecha no disponible':new Intl.DateTimeFormat('es-PE',{day:'numeric',month:'short',year:'numeric'}).format(d);};
const initials=name=>name.trim().split(/\s+/).slice(0,2).map(n=>n[0]).join('').toUpperCase();
const brand=()=>`<a class="brand" href="${href('home')}" aria-label="Nova Plaza, inicio"><img src="${imageUrl('logo.png')}" alt="" width="31" height="40"><span>nova plaza<small>TODO CONECTA AQUÍ</small></span></a>`;
const themeButton=(cls='')=>`<button type="button" class="icon-btn ${cls}" data-action="theme" aria-label="Activar modo ${document.documentElement.dataset.theme==='dark'?'claro':'oscuro'}">${icon(document.documentElement.dataset.theme==='dark'?'sun':'moon')}</button>`;
let toastTimer;
function toast(message,error=false){clearTimeout(toastTimer);document.querySelector('#toast-region').innerHTML=`<div class="toast ${error?'toast-error':''}">${icon(error?'help':'checkCircle')}<span>${esc(message)}</span></div>`;toastTimer=setTimeout(()=>{document.querySelector('#toast-region').innerHTML='';},5000);}
function openModal(title,body){modal.innerHTML=`<div class="modal-inner"><div class="modal-header"><h2 id="modal-title">${esc(title)}</h2><button type="button" class="icon-btn" data-action="close" aria-label="Cerrar ventana">${icon('close')}</button></div>${body}</div>`;if(!modal.open)modal.showModal();}
const closeModal=()=>modal.close();
function nav(){const items=[['home','home','Descubre'],['stores','grid','Explorar tiendas'],['favorites','heart','Mis favoritos'],['cart','bag','Mi carrito'],['profile','user','Mi cuenta'],['wallet','wallet','Mi billetera']];return `<p class="nav-label">TU ESPACIO NOVA</p><nav aria-label="Navegación principal"><ul class="nav-list">${items.map(([route,symbol,label])=>`<li><a class="nav-link ${page===route?'active':''}" ${page===route?'aria-current="page"':''} href="${href(route)}">${icon(symbol)}<span>${label}</span>${route==='favorites'?`<span class="nav-count" data-count="favorites">${S.basket().favorites.length}</span>`:route==='cart'?`<span class="nav-count" data-count="cart">${S.cartCount()}</span>`:''}</a></li>`).join('')}</ul></nav><div class="nav-support"><div class="nav-promo">${icon('spark')}<strong>Encuentra tu próximo favorito.</strong><p>Buenas marcas. Nuevas ideas. Todo en un mismo lugar.</p><a href="${href('home')}#products">Ver la selección ${icon('arrow')}</a></div><button type="button" class="nav-link btn-wide" data-action="help">${icon('help')}<span>¿Te ayudamos?</span></button><button type="button" class="nav-link btn-wide" data-action="report">${icon('message')}<span>Dejar un mensaje</span></button><div class="nav-separator"></div><p class="sidebar-bottom">${icon('pin')} Trujillo, Perú</p></div>`;}
function shell(content){const user=S.currentUser();return `<header class="app-header"><button type="button" class="icon-btn mobile-menu-button" data-action="menu" aria-label="Abrir menú" aria-controls="mobile-nav">${icon('menu')}</button><div class="header-brand">${brand()}</div><form class="header-search" data-form="search" role="search"><label class="sr-only" for="global-search">Buscar productos o marcas</label>${icon('search')}<input id="global-search" type="search" name="q" placeholder="Busca algo que te encante…" value="${esc(ui.search)}" autocomplete="off" maxlength="100"><span class="search-shortcut" aria-hidden="true">/</span></form><div class="header-actions"><span class="demo-badge">DEMO</span>${themeButton()}<a class="icon-btn header-favorite" href="${href('favorites')}" aria-label="Mis favoritos">${icon('heart')}</a><a class="icon-btn header-cart" href="${href('cart')}" aria-label="Mi carrito, ${S.cartCount()} productos">${icon('bag')}<span class="badge-count" data-count="cart">${S.cartCount()}</span></a><a class="header-profile" href="${href(user?'profile':'login')}"><span class="avatar" aria-hidden="true">${user?esc(initials(user.name)):icon('user')}</span><div><strong>${user?esc(user.name.split(' ')[0]):'¡Hola, visitante!'}</strong><small>${user?'Mi cuenta de prueba':'Iniciar sesión'}</small></div><span class="sr-only">${user?'Mi cuenta':'Iniciar sesión'}</span></a></div></header><div class="app-layout"><aside class="sidebar">${nav()}</aside><div class="content-column"><main id="main" class="main-content" tabindex="-1">${content}</main><section class="newsletter" aria-labelledby="newsletter-title"><div><h3 id="newsletter-title">Un poco de Nova en tu correo.</h3><p>Guarda tu interés en nuestra lista de prueba. Esta demo no envía correos.</p></div><form data-form="newsletter" novalidate><label class="sr-only" for="newsletter-email">Tu correo electrónico</label><input id="newsletter-email" name="email" type="email" autocomplete="email" placeholder="Tu correo electrónico" required maxlength="254" aria-describedby="newsletter-email-error"><button class="btn btn-primary" type="submit">Me apunto ${icon('arrow')}</button><span id="newsletter-email-error" class="field-error"></span><span class="form-error" role="alert"></span></form></section><footer class="app-footer"><p>© ${new Date().getFullYear()} Nova Plaza. Una nueva manera de encontrarnos.</p><div class="footer-links"><button type="button" data-action="about">La experiencia Nova</button><button type="button" data-action="privacy">Privacidad de la demo</button><button type="button" data-action="report">Ayuda y contacto</button></div></footer></div></div>`;}
const intro=(title,subtitle,action='')=>`<div class="page-intro"><div><p class="eyebrow">BIENVENIDO A TU NOVA</p><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div>${action}</div>`;
const empty=(symbol,title,description,link='home',label='Explorar productos')=>`<section class="empty-state"><div class="empty-illustration">${icon(symbol)}</div><h2>${esc(title)}</h2><p>${esc(description)}</p><a class="btn btn-primary" href="${href(link)}">${esc(label)} ${icon('arrow')}</a></section>`;
function productCard(p){const favorite=S.basket().favorites.includes(p.id);return `<article class="product-card" data-product="${p.id}"><div class="product-photo"><span class="discount-badge">−${discount(p)}%</span><a href="${href('detail',{product:p.id})}" tabindex="-1" aria-hidden="true"><img src="${imageUrl(p.image)}" alt="" width="280" height="270" loading="lazy" decoding="async"></a><button type="button" class="icon-btn ${favorite?'is-favorite':''}" data-action="favorite" data-id="${p.id}" data-focus="favorite-${p.id}" aria-pressed="${favorite}" aria-label="${favorite?'Quitar':'Guardar'} ${esc(p.name)} en favoritos">${icon('heart')}</button></div><div class="product-info"><p class="product-brand">${esc(storeById(p.store).name)}</p><a class="product-title" href="${href('detail',{product:p.id})}">${esc(p.name)}</a><p class="product-price"><strong>${money(p.price)}</strong><del>${money(p.original)}</del></p><button type="button" class="product-add" data-action="quick-add" data-id="${p.id}">${icon('plus')} Agregar al carrito</button></div></article>`;}
function storeCard(s){const count=products.filter(p=>p.store===s.id).length;return `<a class="store-card" href="${href('detail',{store:s.id})}"><div class="store-logo"><img src="${imageUrl(s.logo)}" alt="" width="120" height="70" loading="lazy"></div><h3>${esc(s.name)}</h3><p>${esc(s.category)}</p><div class="store-card-footer"><span>${count?count+' en la selección':'Conoce la marca'}</span>${icon('arrow')}</div></a>`;}
function filteredProducts(){let list=products.filter(p=>(ui.category==='Todo'||p.category===ui.category)&&(!ui.search||(`${p.name} ${storeById(p.store).name} ${p.category}`).normalize('NFD').replace(/\p{Diacritic}/gu,'').toLowerCase().includes(ui.search.normalize('NFD').replace(/\p{Diacritic}/gu,'').toLowerCase())));if(page==='favorites')list=list.filter(p=>S.basket().favorites.includes(p.id));if(page==='detail'&&query.get('store'))list=list.filter(p=>p.store===query.get('store'));if(ui.sort==='price-asc')list.sort((a,b)=>a.price-b.price);if(ui.sort==='price-desc')list.sort((a,b)=>b.price-a.price);if(ui.sort==='discount')list.sort((a,b)=>discount(b)-discount(a));return list;}
function catalogue(title='Elegidos para ti',subtitle='Pequeños hallazgos. Grandes favoritos.'){return `<section id="products" aria-labelledby="catalogue-title"><div class="section-heading"><div><h2 id="catalogue-title">${esc(title)}</h2><p>${esc(subtitle)}</p></div><span class="section-link">${icon('spark')} Selección Nova</span></div><div class="catalogue-toolbar"><div class="category-pills" aria-label="Filtrar por categoría">${categories.map(c=>`<button type="button" class="category-pill ${ui.category===c?'active':''}" data-action="category" data-category="${c}" aria-pressed="${ui.category===c}">${esc(c)}</button>`).join('')}</div><div class="sort-wrap">${icon('sliders')}<label for="product-sort">Ordenar:</label><select id="product-sort"><option value="featured" ${ui.sort==='featured'?'selected':''}>Recomendados</option><option value="price-asc" ${ui.sort==='price-asc'?'selected':''}>Menor precio</option><option value="price-desc" ${ui.sort==='price-desc'?'selected':''}>Mayor precio</option><option value="discount" ${ui.sort==='discount'?'selected':''}>Mayor descuento</option></select></div></div><div id="catalogue-results"></div></section>`;}
function updateCatalogue(){const target=document.querySelector('#catalogue-results');if(!target)return;const list=filteredProducts();target.innerHTML=`<p class="catalogue-status" role="status"><span>${list.length} ${list.length===1?'producto':'productos'}${ui.search?' para «'+esc(ui.search)+'»':''}</span>${ui.search?'<button type="button" class="btn-text" data-action="clear-search">Limpiar búsqueda</button>':''}</p><div class="product-grid">${list.length?list.slice(0,ui.limit).map(productCard).join(''):empty('search',page==='favorites'&&!S.basket().favorites.length?'Aquí van tus futuros favoritos.':'No encontramos coincidencias.',page==='favorites'&&!S.basket().favorites.length?'Toca el corazón de los productos que te gustan y vuelve a encontrarlos aquí.':'Prueba con otra palabra o cambia la categoría.')}</div>${list.length>ui.limit?'<div class="load-more"><button type="button" class="btn btn-secondary" data-action="load-more">Ver más productos '+icon('down')+'</button></div>':''}`;}
function home(){return `${intro('Todo lo que te gusta, más cerca.','Descubre marcas, encuentra inspiración y arma tu próximo buen plan.',`<span class="welcome-note">${icon('pin')} Hecho para encontrarnos · Trujillo</span>`)}<section class="hero" aria-labelledby="hero-title"><div class="hero-copy"><p class="hero-label"><span></span> TU ESTILO. TUS PLANES. TU NOVA.</p><h2 id="hero-title">Un buen plan.<br><em>Una gran compra.</em></h2><p>De ese par que te encanta a tu próxima pausa favorita. Encuéntralo todo aquí.</p><div class="hero-actions"><a class="btn btn-primary" href="${href('detail',{product:'superstar'})}">Descubrir la selección ${icon('arrow')}</a><a class="hero-link" href="${href('stores')}">Ver tiendas ${icon('chevron')}</a></div></div><div class="hero-art"><span class="hero-orbit" aria-hidden="true"></span><img class="hero-product" src="${imageUrl('hero-superstar.webp')}" alt="Zapatillas Adidas Superstar negras" width="350" height="280" fetchpriority="high"><div class="hero-price"><small>SUPERSTAR ORIGINALS</small>${money(14990)}</div><div class="floating-label">${icon('spark')}<div><strong>Un clásico. Mil posibilidades.</strong><span>El favorito que combina contigo.</span></div></div></div></section><div class="benefit-row"><div class="benefit"><span>${icon('grid')}</span><div><strong>Tus marcas, juntas</strong><small>Moda, tecnología y buenos planes</small></div></div><div class="benefit"><span>${icon('heart')}</span><div><strong>Guarda lo que te gusta</strong><small>Tus favoritos siempre a mano</small></div></div><div class="benefit"><span>${icon('bag')}</span><div><strong>Compra a tu ritmo</strong><small>Organiza tu próximo pedido</small></div></div></div>${catalogue()}<section class="store-section" aria-labelledby="stores-title"><div class="section-heading"><div><h2 id="stores-title">Marcas que conectan contigo.</h2><p>Encuentra un mundo de posibilidades.</p></div><a class="section-link" href="${href('stores')}">Todas las tiendas ${icon('arrow')}</a></div><div class="store-grid home-stores">${stores.slice(0,5).map(storeCard).join('')}</div></section><section class="promo-banner"><div><p class="eyebrow">UN EXTRA PARA TU PRÓXIMO PLAN</p><h2>Estrena tu carrito con NOVA10.</h2><p>10% adicional en pedidos de prueba desde S/ 100.00.</p></div><a class="btn" href="${href('cart')}">Ir a mi carrito ${icon('arrow')}</a></section>`;}
function favorites(){return intro('Tus favoritos. Muy tuyos.','Guarda tus hallazgos y vuelve cuando quieras.')+catalogue('Tu selección personal','Los productos que merecen una segunda mirada.');}
function storesPage(){return intro('Un lugar. Muchas posibilidades.',`Explora las ${stores.length} marcas del catálogo de demostración.`)+`<div class="catalogue-toolbar"><div class="category-pills" aria-label="Categorías de tiendas">${categories.map(c=>`<button type="button" class="category-pill ${c===ui.category?'active':''}" data-action="category" data-category="${c}" aria-pressed="${c===ui.category}">${esc(c)}</button>`).join('')}</div></div><div id="stores-results"></div>`;}
function updateStores(){const target=document.querySelector('#stores-results');if(!target)return;const list=stores.filter(s=>(ui.category==='Todo'||s.category===ui.category)&&s.name.toLowerCase().includes(ui.search.toLowerCase()));target.innerHTML=`<p class="catalogue-status" role="status">${list.length} tiendas</p><div class="store-grid">${list.length?list.map(storeCard).join(''):empty('search','Todavía no encontramos esa marca.','Cambia la búsqueda o explora otra categoría.','stores','Ver todas las tiendas')}</div>`;}
function options(p){return `${p.sizes.length?`<fieldset class="option-group"><legend>Talla <span class="muted">· elige la tuya</span></legend><div class="option-choices">${p.sizes.map((s,i)=>`<label class="option-label"><input type="radio" name="size" value="${esc(s)}" ${i===0?'checked':''} required><span>${esc(s)}</span></label>`).join('')}</div></fieldset>`:''}${p.colors.length?`<fieldset class="option-group"><legend>Color</legend><div class="option-choices">${p.colors.map((c,i)=>`<label class="option-label"><input type="radio" name="color" value="${esc(c)}" ${i===0?'checked':''} required><span>${esc(c)}</span></label>`).join('')}</div></fieldset>`:''}`;}
function detail(){if(query.has('store')){const s=storeById(query.get('store'));if(!s)return empty('search','No encontramos esta tienda.','Vuelve al directorio para descubrir las marcas disponibles.','stores','Explorar tiendas');return `<div class="breadcrumb"><a href="${href('home')}">Inicio</a>${icon('chevron')}<a href="${href('stores')}">Tiendas</a>${icon('chevron')}<span>${esc(s.name)}</span></div><section class="store-hero"><div class="store-logo"><img src="${imageUrl(s.logo)}" alt="Logo de ${esc(s.name)}"></div><div><p class="eyebrow">${esc(s.category)} · SELECCIÓN NOVA</p><h1>${esc(s.name)}</h1><p>${esc(s.description)}</p></div><button type="button" class="btn btn-secondary" data-action="report">Consultar en la demo ${icon('message')}</button></section>${products.some(p=>p.store===s.id)?catalogue('Descubre su selección','Productos del catálogo de demostración.'):empty('grid','Un nuevo plan te espera.','Esta marca tiene una ficha en la demo, pero todavía no tiene productos disponibles para agregar.','stores','Seguir explorando')}`;}
  const p=productById(query.get('product')||'superstar');if(!p)return empty('search','Ese producto no está en la selección.','Encuentra un nuevo favorito entre los productos del catálogo.');const s=storeById(p.store);return `<div class="breadcrumb"><a href="${href('home')}">Inicio</a>${icon('chevron')}<a href="${href('detail',{store:s.id})}">${esc(s.name)}</a>${icon('chevron')}<span>${esc(p.name)}</span></div><section class="detail-layout"><div><div class="detail-image"><img id="detail-photo" src="${imageUrl(p.image)}" alt="${esc(p.name)}" width="600" height="600"></div>${p.gallery?`<div class="thumbnails" aria-label="Galería del producto">${p.gallery.map((img,i)=>`<button type="button" class="thumbnail ${i===0?'active':''}" data-action="gallery" data-image="${img}" aria-label="Ver imagen ${i+1}" aria-pressed="${i===0}"><img src="${imageUrl(img)}" alt="" width="75" height="75"></button>`).join('')}</div>`:''}</div><div class="detail-info"><p class="eyebrow">${esc(s.name)} · ${esc(p.category)}</p><h1>${esc(p.name)}</h1><div class="detail-price"><strong>${money(p.price)}</strong><del>${money(p.original)}</del><span class="discount-badge">Ahorras ${discount(p)}%</span></div><p class="in-stock">Disponible en el catálogo de prueba</p><p class="detail-description">${esc(p.description)}</p><form data-form="detail-add" data-id="${p.id}" novalidate>${options(p)}<div class="detail-buy-row"><button type="submit" class="btn btn-primary">${icon('bag')} Agregar al carrito</button><button type="button" class="icon-btn ${S.basket().favorites.includes(p.id)?'is-favorite':''}" data-action="favorite" data-id="${p.id}" aria-pressed="${S.basket().favorites.includes(p.id)}" aria-label="Guardar ${esc(p.name)} en favoritos">${icon('heart')}</button></div><p class="form-error" role="alert"></p></form><div class="detail-notes"><p class="detail-note">${icon('heart')} Guarda tus favoritos y vuelve a ellos cuando quieras.</p><p class="detail-note">${icon('box')} Elige recojo o entrega al simular tu pedido.</p><p class="detail-note">${icon('shield')} Catálogo de demostración. No se realizan cobros reales.</p></div></div></section><div class="section-heading"><h2>También podrían encantarte.</h2><a class="section-link" href="${href('home')}#products">Seguir explorando ${icon('arrow')}</a></div><div class="product-grid">${products.filter(x=>x.id!==p.id&&x.category===p.category).slice(0,4).map(productCard).join('')}</div>`;}
function cart(){const b=S.basket(),t=S.totals();return intro('Tu próximo buen plan.','Revisa tu selección y dale el último toque.')+(!b.cart.length?empty('bag','Tu carrito tiene espacio para algo bueno.','Encuentra un producto que te encante y agrégalo. Tu selección se guardará en este navegador.'):`<div class="cart-layout"><section aria-label="Productos en tu carrito"><div class="cart-items">${b.cart.map(i=>{const p=productById(i.id),key=esc(S.cartKey(i));return `<article class="cart-item"><a class="cart-item-photo" href="${href('detail',{product:p.id})}" tabindex="-1" aria-hidden="true"><img src="${imageUrl(p.image)}" alt="" width="100" height="100"></a><div><p class="product-brand">${esc(storeById(p.store).name)}</p><h3><a href="${href('detail',{product:p.id})}">${esc(p.name)}</a></h3><p class="cart-item-meta">${[i.size?'Talla '+i.size:'',i.color].filter(Boolean).map(esc).join(' · ')||'Selección Nova'}</p><div class="cart-item-actions"><div class="qty-control"><button type="button" data-action="quantity" data-key="${key}" data-delta="-1" data-focus="minus-${key}" aria-label="Reducir cantidad de ${esc(p.name)}">${icon('minus')}</button><output aria-label="Cantidad">${i.qty}</output><button type="button" data-action="quantity" data-key="${key}" data-delta="1" data-focus="plus-${key}" aria-label="Aumentar cantidad de ${esc(p.name)}">${icon('plus')}</button></div><button type="button" class="remove-link" data-action="remove-cart" data-key="${key}" aria-label="Quitar ${esc(p.name)} del carrito">${icon('trash')} Quitar</button></div></div><div class="cart-item-total">${money((Number.isSafeInteger(i.unitPrice)?i.unitPrice:p.price)*i.qty)}<small>${money(p.price)} por unidad</small></div></article>`;}).join('')}</div><a class="continue-shopping" href="${href('home')}#products">${icon('arrow')} Seguir descubriendo</a></section><aside class="panel cart-summary" aria-label="Resumen del pedido"><h2>Tu resumen</h2><p class="summary-line"><span>Productos (${S.cartCount()})</span><strong>${money(t.subtotal)}</strong></p><p class="summary-line"><span>Recojo de prueba</span><strong>Sin costo</strong></p>${t.discount?`<p class="summary-line discount"><span>Cupón NOVA10</span><strong>−${money(t.discount)}</strong></p>`:''}<div class="summary-total"><span>Total</span><strong>${money(t.total)}</strong></div>${b.coupon?`<p class="coupon-applied">${icon('check')} NOVA10 aplicado <button type="button" data-action="remove-coupon" aria-label="Quitar cupón">${icon('close')}</button></p>`:`<form class="coupon-form" data-form="coupon" novalidate><label class="sr-only" for="coupon-code">Código de cupón</label><input id="coupon-code" name="code" placeholder="¿Tienes un cupón?" maxlength="20" required aria-describedby="coupon-code-error"><button type="submit" class="btn btn-secondary">Aplicar</button><span class="field-error" id="coupon-code-error"></span><span class="form-error" role="alert"></span></form>`}<button type="button" class="btn btn-primary btn-wide" data-action="checkout">Continuar con mi pedido ${icon('arrow')}</button><p class="demo-note">${icon('shield')} Este pedido es una simulación. No se cobra dinero ni se envían órdenes a las tiendas.</p></aside></div>`);}
const field=(id,label,type='text',value='',extra='',hint='')=>`<div class="field"><label for="${id}">${esc(label)}</label><input id="${id}" name="${id}" type="${type}" value="${esc(value)}" ${extra} aria-describedby="${id}-error${hint?' '+id+'-hint':''}">${hint?`<small class="field-hint" id="${id}-hint">${esc(hint)}</small>`:''}<span class="field-error" id="${id}-error"></span></div>`;
const passwordField=(id,label,extra='',strength=false)=>`<div class="field"><label for="${id}">${esc(label)}</label><div class="password-wrap"><input id="${id}" name="${id}" type="password" required maxlength="128" ${extra} aria-describedby="${id}-error${strength?' '+id+'-hint':''}"><button type="button" class="password-toggle" data-action="password" data-target="${id}" aria-label="Mostrar contraseña">${icon('eye')}</button></div>${strength?`<div class="password-strength" data-strength="0" aria-hidden="true"><span></span><span></span><span></span></div><small class="field-hint" id="${id}-hint">Al menos 8 caracteres, una letra y un número.</small>`:''}<span class="field-error" id="${id}-error"></span></div>`;
function accountGate(kind){return intro(kind==='wallet'?'Tu billetera. Tu próximo plan.':'Tu espacio, a tu manera.','Una cuenta de prueba para organizar tus favoritos y pedidos.')+`<section class="empty-state"><div class="empty-illustration">${icon(kind==='wallet'?'wallet':'user')}</div><h2>Todo lo tuyo, en un solo lugar.</h2><p>Inicia una cuenta de prueba o explora la experiencia con nuestro acceso de demostración.</p><div class="hero-actions gate-actions"><a class="btn btn-primary" href="${href('login',{next:kind})}">Iniciar sesión ${icon('arrow')}</a><button type="button" class="btn btn-secondary" data-action="demo">Explorar la demo</button></div><p class="demo-note">La cuenta y el saldo son locales a este navegador. No incluyen servicios bancarios ni autenticación de producción.</p></section>`;}
function orderCard(o){return `<article class="order-card"><div class="order-header"><div><h3>${esc(o.id)}</h3><p>${date(o.date)} · ${o.items?.reduce((n,i)=>n+(Number(i.qty)||0),0)||0} artículos</p></div><span class="status-pill">${icon('check')} Pedido de prueba</span></div><div class="order-products">${(o.items||[]).slice(0,4).map(i=>{const p=productById(i.id);return p?`<img src="${imageUrl(p.image)}" alt="${esc(p.name)}" width="53" height="53">`:'';}).join('')}<strong>${money(Number.isSafeInteger(o.total)?o.total:0)}</strong><button type="button" class="btn btn-text btn-sm" data-action="order-details" data-id="${esc(o.id)}">Ver detalle ${icon('arrow')}</button></div></article>`;}
function profile(){const u=S.currentUser(),b=S.basket();if(!u)return accountGate('profile');return `<section class="profile-hero"><span class="avatar">${esc(initials(u.name))}</span><div><p class="eyebrow muted">TU ESPACIO PERSONAL</p><h1>Hola, ${esc(u.name.split(' ')[0])}.</h1><p>${esc(u.email)} · Cuenta de demostración</p></div><button type="button" class="btn btn-secondary btn-sm" data-action="logout">${icon('logout')} Cerrar sesión</button></section><div class="profile-stats"><div class="stat-card">${icon('box')}<strong>${b.orders.length}</strong><p>Pedidos de prueba</p></div><a class="stat-card" href="${href('favorites')}">${icon('heart')}<strong>${b.favorites.length}</strong><p>Favoritos guardados</p></a><a class="stat-card" href="${href('wallet')}">${icon('wallet')}<strong>${money(b.balance)}</strong><p>Saldo de prueba</p></a></div><div class="tabs" role="tablist" aria-label="Secciones de mi cuenta">${[['orders','Mis pedidos'],['data','Mis datos'],['addresses','Direcciones'],['activity','Mi actividad']].map(([id,label])=>`<button type="button" class="tab" role="tab" id="tab-${id}" aria-controls="profile-panel" aria-selected="${ui.tab===id}" tabindex="${ui.tab===id?'0':'-1'}" data-action="tab" data-tab="${id}">${label}</button>`).join('')}</div><section id="profile-panel" role="tabpanel" aria-labelledby="tab-${ui.tab}" tabindex="0">${ui.tab==='orders'?(b.orders.length?b.orders.map(orderCard).join(''):empty('box','Tu primera historia empieza aquí.','Organiza tu carrito y guarda un pedido de prueba para verlo en tu cuenta.')):ui.tab==='data'?`<div class="panel"><div class="panel-title"><h2>Los detalles que te hacen tú.</h2></div><form class="profile-form" data-form="profile" novalidate>${field('profile-name','Tu nombre','text',u.name,'required minlength="2" maxlength="60" autocomplete="name"')}${field('profile-email','Correo de la cuenta','email',u.email,'readonly autocomplete="email"','El correo identifica tu cuenta de prueba en este navegador.')}<p class="form-error" role="alert"></p><button class="btn btn-primary" type="submit">Guardar cambios ${icon('check')}</button></form></div>`:ui.tab==='addresses'?`<div class="section-heading"><h2>Tus lugares favoritos.</h2><button type="button" class="btn btn-secondary btn-sm" data-action="address">${icon('plus')} Agregar dirección</button></div>${b.addresses.length?`<div class="address-grid">${b.addresses.map(a=>`<article class="panel address-card">${icon('pin')}<h3>${esc(a.label)}</h3><p>${esc(a.address)}</p><p>${esc(a.city)}</p><button type="button" class="icon-btn" data-action="remove-address" data-id="${esc(a.id)}" aria-label="Eliminar dirección ${esc(a.label)}">${icon('trash')}</button></article>`).join('')}</div>`:empty('pin','Aún no has guardado una dirección.','Agrega tus datos de entrega para usarlos al simular tu próximo pedido.','cart','Ver mi carrito')}`:`<div class="panel"><div class="panel-title"><h2>Lo que has compartido.</h2><button type="button" class="btn btn-text btn-sm" data-action="report">Nuevo mensaje ${icon('plus')}</button></div>${b.reports.length||b.comments.length?[...b.reports.map(r=>`<article class="activity-item"><h3>${esc(r.subject)} · ${esc(r.id)}</h3><p>${esc(r.details)}</p>${r.file?`<small>Adjunto registrado: ${esc(r.file.name)} (solo metadatos)</small>`:''}<small>${date(r.date)} · Guardado en este navegador</small></article>`),...b.comments.map(c=>`<article class="activity-item"><h3>Tu comentario</h3><p>${esc(c.text)}</p><small>${date(c.date)} · Guardado en este navegador</small></article>`)].join(''):'<p class="muted small">Tus mensajes y comentarios de prueba aparecerán aquí.</p>'}<form data-form="comment" novalidate><div class="field comment-field"><label for="comment-text">Comparte una idea sobre la experiencia</label><textarea id="comment-text" name="comment-text" placeholder="Nos gustaría leer tu idea…" required minlength="3" maxlength="1000" aria-describedby="comment-text-error"></textarea><span class="field-error" id="comment-text-error"></span></div><p class="form-error" role="alert"></p><button type="submit" class="btn btn-primary">Guardar comentario ${icon('message')}</button><p class="field-hint">Se guarda localmente. No se publica ni se envía a terceros.</p></form></div>`}</section>`;}
function wallet(){const u=S.currentUser(),b=S.basket();if(!u)return accountGate('wallet');return `${intro('Tu billetera, sin complicaciones.','Un espacio de prueba para explorar cómo se organiza tu saldo.')}<div class="wallet-layout"><section><div class="wallet-card"><div class="wallet-card-header"><span class="brand">nova plaza</span>${icon('wallet')}</div><div><p class="eyebrow">SALDO DE DEMOSTRACIÓN</p><p class="wallet-balance">${money(b.balance)}</p></div><div class="wallet-card-bottom"><span>${esc(u.name)}</span><span>CUENTA DE PRUEBA</span></div></div><div class="panel"><div class="panel-title"><h2>Dale espacio a tu próximo plan.</h2></div><p class="small muted">Agrega saldo ficticio y úsalo al guardar pedidos de demostración.</p><button type="button" class="btn btn-primary btn-wide wallet-deposit" data-action="deposit">${icon('plus')} Agregar saldo de prueba</button><div class="info-list"><p class="info-item">${icon('shield')} El saldo no es dinero real y no se conecta con una entidad bancaria.</p><p class="info-item">${icon('clock')} Las recargas y pedidos se registran en este navegador.</p></div></div></section><section class="panel"><div class="panel-title"><h2>Tus movimientos</h2><span class="demo-badge">DEMO</span></div>${b.transactions.length?b.transactions.slice(0,20).map(t=>`<div class="transaction"><span class="transaction-icon">${icon(t.amount>0?'plus':'bag')}</span><div><strong>${esc(t.label)}</strong><p>${date(t.date)}</p></div><span class="transaction-amount ${t.amount>0?'positive':''}">${t.amount>0?'+':'−'}${money(Math.abs(t.amount))}</span></div>`).join(''):'<p class="muted small">Tu historia de movimientos empieza con una recarga de prueba.</p>'}</section></div>`;}
function auth(){const register=page==='register';return `<main id="main" class="auth-layout"><section class="auth-art" aria-label="Bienvenido a Nova Plaza">${brand()}<div class="auth-art-copy"><p class="eyebrow">TODAS TUS POSIBILIDADES, CONECTADAS</p><h2>Un espacio para<br><em>lo que te gusta.</em></h2><p>Tus marcas favoritas. Tus próximos planes. Una experiencia hecha para encontrarnos.</p><img class="auth-mall" src="${imageUrl('bg-first-screen.jpg')}" alt="Interior de un centro comercial" width="520" height="220"></div><p class="auth-art-bottom">${icon('pin')} Trujillo, Perú · Experiencia Nova</p></section><section class="auth-form-side">${themeButton('auth-theme')}<div class="auth-inner"><p class="eyebrow">${register?'EMPIEZA ALGO BUENO':'QUÉ BUENO VERTE'}</p><h1>${register?'Haz espacio para ti.':'Bienvenido de vuelta.'}</h1><p class="auth-subtitle">${register?'Crea tu cuenta de prueba y reúne tus favoritos, pedidos y próximos planes.':'Entra a tu cuenta de prueba y continúa donde lo dejaste.'}</p><form data-form="${register?'register':'login'}" novalidate>${register?field('auth-name','Tu nombre','text','','required minlength="2" maxlength="60" autocomplete="name"'):''}${field('auth-email','Correo electrónico','email','','required maxlength="254" autocomplete="email"','Ejemplo: hola+nova@correo.technology')}${passwordField('auth-password',register?'Crea una contraseña':'Contraseña',`autocomplete="${register?'new-password':'current-password'}"`,register)}${register?passwordField('auth-confirm','Confirma tu contraseña','autocomplete="new-password"'):`<div class="form-row"><button type="button" data-action="recover">¿Olvidaste tu contraseña?</button></div>`}${register?`<label class="checkbox-label"><input type="checkbox" id="demo-consent" name="consent" required aria-describedby="demo-consent-error"><span>Entiendo que es una cuenta de demostración y que mis datos se guardan en este navegador.</span></label><span class="field-error" id="demo-consent-error"></span>`:''}<p class="form-error" role="alert"></p><button class="btn btn-primary btn-wide" type="submit">${register?'Crear mi cuenta':'Iniciar sesión'} ${icon('arrow')}</button></form><div class="divider">O DESCUBRE LA EXPERIENCIA</div><button type="button" class="btn btn-secondary btn-wide" data-action="demo">${icon('spark')} Explorar la demo</button><p class="auth-bottom">${register?'¿Ya tienes tu espacio?':'¿Todavía no tienes cuenta?'}<a href="${href(register?'login':'register')}">${register?'Inicia sesión':'Créala aquí'}</a></p><p class="auth-local-note">Demo local: no uses tu contraseña habitual.<br>No hay pagos reales ni envío de correos.</p></div><a class="auth-back" href="${href('home')}">${icon('arrow')} Volver a descubrir</a></section></main>`;}
function render(){const active=document.activeElement,focus=active?.dataset.focus,id=active?.id;app.innerHTML=['login','register'].includes(page)?auth():shell(({home,favorites,stores:storesPage,detail,cart,profile,wallet}[page]||home)());updateCatalogue();updateStores();if(focus)document.querySelector(`[data-focus="${CSS.escape(focus)}"]`)?.focus({preventScroll:true});else if(id)document.getElementById(id)?.focus({preventScroll:true});}
function refreshCounts(){document.querySelectorAll('[data-count="cart"]').forEach(el=>el.textContent=S.cartCount());document.querySelectorAll('[data-count="favorites"]').forEach(el=>el.textContent=S.basket().favorites.length);document.querySelector('.header-cart')?.setAttribute('aria-label',`Mi carrito, ${S.cartCount()} productos`);}
function refreshFavorites(id){const on=S.basket().favorites.includes(id),p=productById(id);document.querySelectorAll(`[data-action="favorite"][data-id="${id}"]`).forEach(b=>{b.classList.toggle('is-favorite',on);b.setAttribute('aria-pressed',on);b.setAttribute('aria-label',`${on?'Quitar':'Guardar'} ${p.name} en favoritos`);});refreshCounts();}
function quickAdd(id){const p=productById(id);if(!p)return;if(!p.sizes.length&&!p.colors.length){S.addCart(p.id);refreshCounts();toast('Un buen hallazgo. '+p.name+' está en tu carrito.');return;}openModal('Un detalle antes de agregarlo.',`<div class="modal-product"><img src="${imageUrl(p.image)}" alt="${esc(p.name)}"><div><h3>${esc(p.name)}</h3><p>${money(p.price)}</p></div></div><form data-form="detail-add" data-id="${p.id}" novalidate>${options(p)}<p class="form-error" role="alert"></p><div class="modal-actions"><button type="button" class="btn btn-secondary" data-action="close">Seguir viendo</button><button type="submit" class="btn btn-primary">Agregar al carrito ${icon('bag')}</button></div></form>`);}
function authGateCheckout(){openModal('Tu pedido merece su propio espacio.',`<p class="modal-description">Inicia una cuenta de prueba para guardar tu pedido, o usa el acceso de demostración. No se realizará ningún cobro.</p><div class="modal-actions"><a class="btn btn-secondary" href="${href('login',{next:'cart'})}">Iniciar sesión</a><button type="button" class="btn btn-primary" data-action="demo-checkout">Continuar con la demo ${icon('arrow')}</button></div>`);}
function checkout(){if(!S.currentUser()){authGateCheckout();return;}if(!S.basket().cart.length)return;const u=S.currentUser(),a=S.basket().addresses[0],t=S.totals();openModal('El último paso de tu buen plan.',`<p class="modal-description">Guarda un pedido de prueba en tu cuenta. No se cobra dinero ni se despachan productos.</p><form data-form="checkout" novalidate><div class="form-grid">${field('order-name','Nombre de quien recibe','text',u.name,'required minlength="2" maxlength="60" autocomplete="name"')}${field('order-email','Correo electrónico','email',u.email,'required maxlength="254" autocomplete="email"')}</div><fieldset class="option-group"><legend>¿Cómo lo organizarías?</legend><label class="radio-card"><input type="radio" name="delivery" value="pickup" checked><span><strong>Recojo de prueba · sin costo</strong><small>No genera una reserva en la tienda.</small></span></label><label class="radio-card"><input type="radio" name="delivery" value="delivery"><span><strong>Entrega de prueba · S/ 9.90</strong><small>Una tarifa ficticia para explorar el flujo.</small></span></label></fieldset><div id="delivery-fields" hidden>${field('order-address','Dirección de entrega','text',a?.address||'','disabled minlength="8" maxlength="200" autocomplete="street-address"')}${field('order-phone','Celular · 9 dígitos','tel','','disabled pattern="9[0-9]{8}" maxlength="9" autocomplete="tel-national" inputmode="numeric"','Ejemplo: 987654321. Solo se guarda en este navegador.')}</div><fieldset class="option-group"><legend>Pago de demostración</legend><label class="radio-card"><input type="radio" name="payment" value="demo" checked><span><strong>Simular sin usar saldo</strong><small>No solicita datos de tarjeta ni cobra dinero.</small></span></label><label class="radio-card"><input type="radio" name="payment" value="wallet"><span><strong>Usar billetera de prueba</strong><small>Tu saldo ficticio: ${money(S.basket().balance)}</small></span></label></fieldset><div class="checkout-review"><p class="summary-line"><span>Subtotal</span><strong>${money(t.subtotal)}</strong></p>${t.discount?`<p class="summary-line discount"><span>Descuento NOVA10</span><strong>−${money(t.discount)}</strong></p>`:''}<p class="summary-line"><span>Entrega de prueba</span><strong id="checkout-shipping">Sin costo</strong></p><p class="summary-line"><strong>Total de prueba</strong><strong id="checkout-total">${money(t.total)}</strong></p></div><label class="checkbox-label"><input type="checkbox" id="order-consent" name="consent" required aria-describedby="order-consent-error"><span>Entiendo que es un pedido de demostración, sin cobro ni entrega real.</span></label><span class="field-error" id="order-consent-error"></span><p class="form-error" role="alert"></p><div class="modal-actions"><button type="button" class="btn btn-secondary" data-action="close">Volver al carrito</button><button type="submit" class="btn btn-primary">Guardar pedido de prueba ${icon('check')}</button></div></form>`);}
function showReport(){openModal('Cuéntanos qué tienes en mente.',`<p class="modal-description">Tu mensaje se guardará en la actividad de esta demo. No se envía a una tienda ni a un equipo de soporte.</p><form data-form="report" novalidate><div class="field"><label for="report-subject">¿Sobre qué quieres escribir?</label><select id="report-subject" name="subject" required aria-describedby="report-subject-error"><option value="">Elige un tema</option><option>Una idea para Nova</option><option>Consulta sobre un producto</option><option>Problema con la demo</option><option>Otra consulta</option></select><span class="field-error" id="report-subject-error"></span></div><div class="field"><label for="report-details">Tu mensaje</label><textarea id="report-details" name="details" placeholder="Cuéntanos un poco más…" required minlength="12" maxlength="2000" aria-describedby="report-details-error"></textarea><span class="field-error" id="report-details-error"></span></div><div class="field"><label for="report-file">Adjunto opcional</label><input id="report-file" name="file" type="file" accept=".pdf,.png,.jpg,.jpeg" aria-describedby="report-file-hint report-file-error"><small class="field-hint" id="report-file-hint">PDF, PNG o JPG de hasta 2 MB. Se guarda solo su nombre y tamaño, no el archivo.</small><span class="field-error" id="report-file-error"></span></div><p class="form-error" role="alert"></p><div class="modal-actions"><button type="button" class="btn btn-secondary" data-action="close">Cancelar</button><button type="submit" class="btn btn-primary">Guardar mensaje ${icon('message')}</button></div></form>`);}
function showAddress(){openModal('Un lugar para tus próximos planes.',`<form data-form="address" novalidate>${field('address-label','Nombre de la dirección','text','','required minlength="2" maxlength="40" placeholder="Casa, oficina…"')}${field('address-line','Dirección','text','','required minlength="8" maxlength="200" autocomplete="street-address"')}${field('address-city','Ciudad','text','Trujillo','required minlength="2" maxlength="60" autocomplete="address-level2"')}<p class="form-error" role="alert"></p><div class="modal-actions"><button type="button" class="btn btn-secondary" data-action="close">Cancelar</button><button type="submit" class="btn btn-primary">Guardar dirección ${icon('check')}</button></div></form>`);}
function showRecovery(){openModal('Recupera tu cuenta de prueba.',`<p class="modal-description">Usa el código que recibiste al crear tu cuenta. Esta demo no envía enlaces de recuperación por correo.</p><form data-form="recover" novalidate>${field('recover-email','Correo de la cuenta','email','','required maxlength="254" autocomplete="email"')}${field('recover-code','Código de recuperación','text','','required maxlength="30" placeholder="NOVA-XXXXXXXXXXXX" autocomplete="off"')}${passwordField('recover-password','Nueva contraseña','autocomplete="new-password"',true)}${passwordField('recover-confirm','Confirma la nueva contraseña','autocomplete="new-password"')}<p class="form-error" role="alert"></p><div class="modal-actions"><button type="button" class="btn btn-secondary" data-action="close">Cancelar</button><button type="submit" class="btn btn-primary">Cambiar contraseña ${icon('lock')}</button></div></form>`);}
function fieldError(control,message){const target=document.getElementById(control.id+'-error');if(target)target.textContent=message;else control.form.querySelector('.form-error').textContent=message;control.setAttribute('aria-invalid','true');}
function validate(form){form.querySelectorAll('.field-error,.form-error').forEach(e=>e.textContent='');form.querySelectorAll('[aria-invalid]').forEach(e=>e.removeAttribute('aria-invalid'));let first;
  for(const c of form.elements){if(!c.willValidate||c.type==='submit'||c.type==='button')continue;let message='';if(c.required && (c.type==='checkbox'?!c.checked:!c.value.trim()))message=c.type==='checkbox'?'Marca esta casilla para continuar.':'Completa este campo.';else if(c.type==='email'&&c.value&&!c.checkValidity())message='Ingresa un correo válido, por ejemplo hola@correo.com.';else if(c.value&&c.minLength>0&&c.value.trim().length<c.minLength)message=`Escribe al menos ${c.minLength} caracteres.`;else if(c.validity.patternMismatch)message=c.type==='tel'?'Ingresa 9 dígitos y comienza con 9.':'Revisa el formato de este campo.';else if(c.validity.rangeUnderflow||c.validity.rangeOverflow)message=`El importe debe estar entre ${c.min} y ${c.max}.`;if(message){fieldError(c,message);first ||= c;}}
  const pass=form.querySelector('[autocomplete="new-password"]');if(pass?.value&&!S.validatePassword(pass.value)){fieldError(pass,'Usa al menos 8 caracteres, una letra y un número.');first ||= pass;}
  const confirm=form.querySelector('#auth-confirm,#recover-confirm');if(confirm && confirm.value!==pass?.value){fieldError(confirm,'Las contraseñas no coinciden.');first ||= confirm;}
  if(first){first.focus();return false;}return true;
}
async function submit(form){if(!validate(form))return;const type=form.dataset.form,values=new FormData(form),get=n=>String(values.get(n)||'').trim();const button=form.querySelector('[type="submit"]');if(button){button.disabled=true;button.setAttribute('aria-busy','true');}
  try {
    if(type==='search'){location.href=href(page==='stores'?'stores':'home',{q:get('q')});}
    else if(type==='login'){await S.login(get('auth-email'),String(values.get('auth-password')));location.href=href(['cart','wallet','profile'].includes(query.get('next'))?query.get('next'):'profile');}
    else if(type==='register'){const code=await S.register(get('auth-name'),get('auth-email'),String(values.get('auth-password')));openModal('Ya tienes tu espacio Nova.',`<div class="success-message"><div class="success-icon">${icon('check')}</div><h3>¡Qué bueno encontrarnos!</h3><p>Tu cuenta de prueba está creada. Guarda este código para recuperar tu contraseña en este navegador.</p></div><div class="recovery-code"><span id="recovery-code">${esc(code)}</span><button type="button" class="icon-btn" data-action="copy-recovery" aria-label="Copiar código de recuperación">${icon('copy')}</button></div><p class="field-hint">El código se muestra una sola vez. No uses contraseñas de tus cuentas reales.</p><div class="modal-actions"><a class="btn btn-primary btn-wide" href="${href('profile')}">Ir a mi espacio ${icon('arrow')}</a></div>`);form.reset();}
    else if(type==='recover'){await S.recover(get('recover-email'),get('recover-code'),String(values.get('recover-password')));closeModal();toast('Tu contraseña de prueba está actualizada. Ya puedes iniciar sesión.');}
    else if(type==='detail-add'){S.addCart(form.dataset.id,get('size'),get('color'));if(modal.contains(form))closeModal();refreshCounts();toast('Listo. Tu selección está guardada en el carrito.');}
    else if(type==='coupon'){S.applyCoupon(get('code'));render();toast('NOVA10 aplicado. Un buen extra para tu plan.');}
    else if(type==='newsletter'){S.subscribe(get('email'));form.reset();toast('Tu correo está guardado en la lista de prueba. No se enviarán mensajes.');}
    else if(type==='profile'){S.updateProfile(get('profile-name'));render();toast('Tu nombre está actualizado.');}
    else if(type==='address'){if(!S.currentUser())throw new Error('Inicia una sesión de prueba para guardar una dirección.');S.saveAddress({label:get('address-label'),address:get('address-line'),city:get('address-city')});closeModal();render();toast('Tu dirección quedó guardada.');}
    else if(type==='deposit'){const raw=get('deposit-amount');if(!/^\d+(?:[.,]\d{1,2})?$/.test(raw))throw new Error('Usa un importe con hasta dos decimales.');S.deposit(Math.round(Number(raw.replace(',','.'))*100));closeModal();render();toast('Saldo de prueba agregado. No se ha cobrado dinero.');}
    else if(type==='checkout'){const order=S.placeOrder({name:get('order-name'),email:get('order-email'),delivery:get('delivery'),address:get('order-address'),phone:get('order-phone'),payment:get('payment')});render();openModal('Tu próximo plan ya tiene nombre.',`<div class="success-message"><div class="success-icon">${icon('checkCircle')}</div><h3>Pedido de prueba guardado.</h3><p>Referencia <strong>${esc(order.id)}</strong><br>Total de prueba: <strong>${money(order.total)}</strong><br>No se realizó ningún cobro ni se envió una orden a la tienda.</p></div><div class="modal-actions"><a class="btn btn-primary btn-wide" href="${href('profile')}">Ver mi pedido ${icon('arrow')}</a></div>`);}
    else if(type==='report'){const file=values.get('file');if(file?.size){if(file.size>2*1024*1024){fieldError(form.querySelector('#report-file'),'El archivo debe pesar como máximo 2 MB.');return;}if(!/\.(pdf|png|jpe?g)$/i.test(file.name)||!['application/pdf','image/png','image/jpeg',''].includes(file.type)){fieldError(form.querySelector('#report-file'),'Elige un PDF, PNG o JPG.');return;}}const r=S.saveReport({subject:get('subject'),details:get('details'),file:file?.size?{name:file.name.slice(0,120),size:file.size,type:file.type}:null});closeModal();if(page==='profile')render();toast('Mensaje '+r.id+' guardado localmente. No se envió a terceros.');}
    else if(type==='comment'){S.saveComment(get('comment-text'));render();toast('Tu comentario está guardado en la actividad de la demo.');}
  } catch(error){const target=form.querySelector('.form-error');if(target){target.textContent=error.message;target.setAttribute('tabindex','-1');target.focus();}else toast(error.message,true);}
  finally {if(button?.isConnected){button.disabled=false;button.removeAttribute('aria-busy');}}
}
async function action(button){const name=button.dataset.action,id=button.dataset.id;
  if(name==='theme'){const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';try{localStorage.setItem('nova-theme',theme);}catch{toast('El tema se aplicará durante esta visita.',true);}document.documentElement.dataset.theme=theme;document.querySelectorAll('[data-action="theme"]').forEach(b=>{b.innerHTML=icon(theme==='dark'?'sun':'moon');b.setAttribute('aria-label','Activar modo '+(theme==='dark'?'claro':'oscuro'));});}
  else if(name==='menu'){drawer.innerHTML=`<div class="modal-header"><h2 id="mobile-nav-title" class="sr-only">Menú Nova Plaza</h2>${brand()}<button type="button" class="icon-btn" data-action="close-menu" aria-label="Cerrar menú">${icon('close')}</button></div>${nav()}`;drawer.showModal();}
  else if(name==='close-menu')drawer.close();else if(name==='close')closeModal();
  else if(name==='favorite'){S.toggleFavorite(id);if(page==='favorites')updateCatalogue();else refreshFavorites(id);refreshCounts();toast(S.basket().favorites.includes(id)?'Guardado en tus favoritos. Muy tuyo.':'Producto retirado de tus favoritos.');}
  else if(name==='quick-add')quickAdd(id);
  else if(name==='category'){ui.category=button.dataset.category;ui.limit=8;document.querySelectorAll('[data-action="category"]').forEach(b=>{b.classList.toggle('active',b.dataset.category===ui.category);b.setAttribute('aria-pressed',b.dataset.category===ui.category);});updateCatalogue();updateStores();}
  else if(name==='clear-search'){ui.search='';document.querySelector('#global-search').value='';updateCatalogue();updateStores();}
  else if(name==='load-more'){ui.limit+=8;updateCatalogue();}
  else if(name==='quantity'){S.changeQty(button.dataset.key,Number(button.dataset.delta));render();}
  else if(name==='remove-cart'){S.removeCart(button.dataset.key);render();toast('Producto retirado del carrito.');}
  else if(name==='remove-coupon'){S.removeCoupon();render();}
  else if(name==='checkout')checkout();
  else if(name==='demo'||name==='demo-checkout'){button.disabled=true;try{await S.enterDemo();if(name==='demo-checkout'){closeModal();render();checkout();}else if(['login','register'].includes(page))location.href=href(['wallet','cart','profile'].includes(query.get('next'))?query.get('next'):'home');else render();}finally{if(button.isConnected)button.disabled=false;}}
  else if(name==='logout'){S.logout();render();toast('Tu sesión de prueba está cerrada.');}
  else if(name==='tab'){ui.tab=button.dataset.tab;render();document.querySelector('#tab-'+ui.tab)?.focus({preventScroll:true});}
  else if(name==='password'){const input=document.getElementById(button.dataset.target),show=input.type==='password';input.type=show?'text':'password';button.innerHTML=icon(show?'eyeOff':'eye');button.setAttribute('aria-label',show?'Ocultar contraseña':'Mostrar contraseña');}
  else if(name==='gallery'){document.querySelector('#detail-photo').src=imageUrl(button.dataset.image);document.querySelectorAll('.thumbnail').forEach(b=>{const on=b===button;b.classList.toggle('active',on);b.setAttribute('aria-pressed',on);});}
  else if(name==='report'){drawer.close();showReport();}
  else if(name==='address')showAddress();else if(name==='remove-address'){S.removeAddress(id);render();toast('Dirección retirada.');}
  else if(name==='recover')showRecovery();
  else if(name==='copy-recovery'){await navigator.clipboard.writeText(document.querySelector('#recovery-code').textContent);toast('Código copiado. Guárdalo en un lugar seguro.');}
  else if(name==='deposit')openModal('Un impulso para tu próximo plan.',`<p class="modal-description">Agrega un importe ficticio. No se carga ninguna tarjeta ni cuenta bancaria.</p><form data-form="deposit" novalidate>${field('deposit-amount','Importe de prueba en soles','number','100','required min="1" max="5000" step="0.01" inputmode="decimal"','De S/ 1.00 a S/ 5,000.00 por recarga.')}<p class="form-error" role="alert"></p><div class="modal-actions"><button type="button" class="btn btn-secondary" data-action="close">Cancelar</button><button type="submit" class="btn btn-primary">Agregar saldo ficticio ${icon('plus')}</button></div></form>`);
  else if(name==='order-details'){const o=S.basket().orders.find(o=>o.id===id);if(!o)return;openModal(o.id,`<p class="modal-description">${date(o.date)} · Pedido guardado localmente, sin cobro ni entrega real.</p>${(o.items||[]).map(i=>{const p=productById(i.id);return p?`<p class="summary-line"><span>${esc(i.name||p.name)} × ${i.qty}<br><small class="muted">${esc([i.size,i.color].filter(Boolean).join(' · '))}</small></span><strong>${money((Number.isSafeInteger(i.unitPrice)?i.unitPrice:p.price)*i.qty)}</strong></p>`:'';}).join('')}<div class="summary-total"><span>Total de prueba</span><strong>${money(o.total)}</strong></div><p class="demo-note">${icon('pin')} ${o.details?.delivery==='delivery'?'Entrega de prueba: '+esc(o.details?.address):'Recojo de demostración.'}</p>`);}
  else if(['help','about','privacy'].includes(name)){drawer.close();const texts={help:['Tu próximo plan, sin dudas.',`<div class="info-list"><p class="info-item">${icon('search')} Encuentra productos con la búsqueda y las categorías. Ordena por precio o descuento.</p><p class="info-item">${icon('heart')} Toca un corazón para guardar tus favoritos. Se conservan al volver a este navegador.</p><p class="info-item">${icon('bag')} Elige tus productos, revisa cantidades y aplica NOVA10 desde S/ 100.00.</p><p class="info-item">${icon('wallet')} Crea una cuenta de prueba o usa el acceso demo para explorar pedidos y saldo ficticio.</p></div><p class="demo-note">Esta experiencia no conecta con tiendas, bancos ni servicios de correo. Los mensajes y pedidos se guardan localmente.</p><div class="modal-actions"><button type="button" class="btn btn-primary" data-action="report">Dejar un mensaje ${icon('message')}</button></div>`],about:['Todo conecta aquí.',`<p class="modal-description">Nova Plaza reúne las imágenes y marcas del proyecto original en una experiencia renovada para explorar, guardar favoritos y organizar pedidos de prueba.</p><p class="modal-description">Este catálogo es una demostración. Los precios, descuentos y cantidades ilustran el flujo y no son una oferta comercial vigente.</p>`],privacy:['Tus datos, en esta demo.',`<p class="modal-description">Cuentas, favoritos, pedidos, mensajes y direcciones se guardan en el almacenamiento de este navegador. Las contraseñas se almacenan como verificadores derivados, no como texto. Esto no sustituye una autenticación con servidor.</p><p class="modal-description">No se envían correos ni archivos. Los adjuntos conservan únicamente nombre, tipo y tamaño. Eliminar los datos del sitio desde tu navegador borra la información local; perderás el historial y las cuentas de prueba.</p>`]};openModal(...texts[name]);}
}
document.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(!button||button.disabled)return;event.preventDefault();action(button).catch(error=>toast(error.message,true));});
document.addEventListener('submit',event=>{const form=event.target.closest('form[data-form]');if(!form)return;event.preventDefault();submit(form).catch(error=>toast(error.message,true));});
let searchTimer;
document.addEventListener('input',event=>{const el=event.target;if(el.id==='global-search'){clearTimeout(searchTimer);searchTimer=setTimeout(()=>{ui.search=el.value.trim();ui.limit=8;updateCatalogue();updateStores();},180);}if(el.type==='password'||el.type==='text'&&el.autocomplete==='new-password'){const strength=el.closest('.field')?.querySelector('.password-strength');if(strength){const p=el.value;strength.dataset.strength=p.length===0?'0':S.validatePassword(p)?(p.length>=12&&/[^\p{L}\d]/u.test(p)?'3':'2'):'1';}}if(el.hasAttribute('aria-invalid')){el.removeAttribute('aria-invalid');const err=document.getElementById(el.id+'-error');if(err)err.textContent='';}});
document.addEventListener('change',event=>{if(event.target.id==='product-sort'){ui.sort=event.target.value;updateCatalogue();}if(event.target.name==='delivery'){const on=event.target.value==='delivery';document.querySelector('#delivery-fields').hidden=!on;document.querySelectorAll('#delivery-fields input').forEach(i=>{i.disabled=!on;i.required=on;});const t=S.totals(on);document.querySelector('#checkout-shipping').textContent=on?money(t.shipping):'Sin costo';document.querySelector('#checkout-total').textContent=money(t.total);}});
document.addEventListener('keydown',event=>{if(event.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)&&!modal.open&&!drawer.open){event.preventDefault();document.querySelector('#global-search')?.focus();}if(event.target.getAttribute('role')==='tab'&&['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();const tabs=[...document.querySelectorAll('[role="tab"]')],i=tabs.indexOf(event.target);const next=event.key==='Home'?0:event.key==='End'?tabs.length-1:(i+(event.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[next].click();}});
for(const dialog of [modal,drawer])dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});
matchMedia('(min-width: 1101px)').addEventListener('change',event=>{if(event.matches&&drawer.open)drawer.close();});
window.addEventListener('storage',event=>{if(['novaplaza-v3','nova-theme'].includes(event.key))location.reload();});
render();
if(!S.storageStatus())toast('Se restableció el estado local. Guarda un cambio para comprobar el almacenamiento de la demo.',true);
